import{_ as t}from"./chunks/qgc_setup_power_px4.DDZ0BUEo.js";import{_ as a,c as o,a8 as r,o as i}from"./chunks/framework.BDnHobkS.js";const b=JSON.parse('{"title":"배터리 파워 모듈 설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko/config/battery.md","filePath":"ko/config/battery.md"}'),s={name:"ko/config/battery.md"};function n(l,e,c,d,h,p){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="배터리-파워-모듈-설정" tabindex="-1">배터리 파워 모듈 설정 <a class="header-anchor" href="#배터리-파워-모듈-설정" aria-label="Permalink to &quot;배터리 파워 모듈 설정&quot;">​</a></h1><p>전원 설정 방법에 대하여 설명합니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These instructions require that the vehicle has a <a href="./../power_module/">Power Module (PM)</a>, or other hardware that can measure the battery voltage and (optionally) the current.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This tuning is not needed for <a href="./../smart_batteries/">Smart/MAVLink Batteries</a>: batteries that can supply a reliable indication of remaining charge.</p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>Battery Estimation Tuning uses the measured voltage and current (if available) to estimate the remaining battery capacity. This is important because it allows PX4 to take action when the vehicle is close to running out of power and crashing (and also to prevent battery damage due to deep-discharge).</p><p>PX4는 여러가지 효과적인 용량 추정 방법을 제공합니다.</p><ol><li><a href="#basic_settings">Basic Battery Settings</a> (default): raw measured voltage is compared to the range between &quot;empty&quot; and &quot;full&quot; voltages. 측정 전압 (및 해당 용량)은 부하시 변동으로 인하여 대략적인 추정치입니다.</li><li><a href="#load_compensation">Voltage-based Estimation with Load Compensation</a>: Counteracts the effects of loading on the capacity calculation.</li><li><a href="#current_integration">Voltage-based Estimation with Current Integration</a>: Fuses the load-compensated voltage-based estimate for the available capacity with a current-based estimate of the charge that has been consumed. 그 결과 스마트 배터리와 비슷한 용량 추정치를 얻을 수 있습니다.</li></ol><p>기타 다른 방법들은 이러한 방법들을 응용한 것입니다. 사용하는 접근 방식은 차량의 전원 모듈이 전류를 측정 가능 여부에 따라 다릅니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The instructions below refer to battery 1 calibration parameters: <code>BAT1_*</code>. Other batteries use the <code>BATx_*</code> parameters, where <code>x</code> is the battery number. All battery calibration parameters <a href="./../advanced_config/parameter_reference.html#battery-calibration">are listed here</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In addition to PX4 configuration discussed here, you should ensure that the ESC&#39;s low voltage cutoff is either disabled or set below the expected minimum voltage. 이렇게 하면 PX4에서 배터리 오류 안전 동작을 관리하고 배터리가 충전되어있는 동안 ESC가 차단되지 않도록합니다 (선택한 &quot;빈 배터리&quot;설정에 따라).</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../power_systems/battery_chemistry.html">Battery Chemistry Overview</a> explains the difference between the main battery types, and how that impacts the battery settings.</p></div><h2 id="basic_settings" tabindex="-1">Basic Battery Settings (default) <a class="header-anchor" href="#basic_settings" aria-label="Permalink to &quot;Basic Battery Settings (default) {#basic_settings}&quot;">​</a></h2><p>기본 배터리 설정은 용량 추정 기본 방법을 사용하도록 PX4를 설정합니다. 이 방법은 측정된 원시 배터리 전압을 &quot;빈&quot;셀과 &quot;충전&quot;셀 (셀 수에 따라 조정 됨)에 대한 셀 전압 범위와 비교합니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This approach results in relatively coarse estimations due to fluctuations in the estimated charge as the measured voltage changes under load.</p></div><p>배터리 1의 기본 설정 방법</p><ol><li>Start <em>QGroundControl</em> and connect the vehicle.</li><li>Select <strong>&quot;Q&quot; icon &gt; Vehicle Setup &gt; Power</strong> (sidebar) to open <em>Power Setup</em>.</li></ol><p>배터리 특성을 나타내는 기본 설정이 제공됩니다. 아래 섹션에서는 각 필드에 대해 설정할 값들을 설명합니다.</p><p><img src="'+t+'" alt="QGC Power Setup"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing <em>QGroundControl</em> only allows you to set values for battery 1 in this view. For vehicles with multiple batteries you&#39;ll need to directly <a href="./../advanced_config/parameters.html">set the parameters</a> for battery 2 (<code>BAT2_*</code>), as described in the following sections.</p></div><h3 id="셀의-갯수-직렬-연결" tabindex="-1">셀의 갯수(직렬 연결) <a class="header-anchor" href="#셀의-갯수-직렬-연결" aria-label="Permalink to &quot;셀의 갯수(직렬 연결)&quot;">​</a></h3><p>이것은 배터리에 직렬로 연결된 셀 수를 설정합니다. 일반적으로 배터리에 &quot;S&quot;앞에 숫자로 표시합니다 (예 : &quot;3S&quot;, &quot;5S&quot;).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The voltage across a single galvanic battery cell is dependent on the <a href="./../power_systems/battery_chemistry.html">chemical properties of the battery type</a>. Lithium-Polymer (LiPo) batteries and Lithium-Ion batteries both have the same <em>nominal</em> cell voltage of 3.7V. In order to achieve higher voltages (which will more efficiently power a vehicle), multiple cells are connected in <em>series</em>. 터미널의 배터리 전압은 셀 전압의 배수입니다.</p></div><p>셀 개수가 제공되지 않은 경우 배터리 전압을 단일 셀의 공칭 전압으로 나누어 계산할 수 있습니다. 아래의 표는 배터리의 전압-셀 관계를 나타냅니다.</p><table tabindex="0"><thead><tr><th>셀</th><th>LiPo (V)</th><th>LiIon (V)</th></tr></thead><tbody><tr><td>1S</td><td>3.7</td><td>3.7</td></tr><tr><td>2S</td><td>7.4</td><td>7.4</td></tr><tr><td>3S</td><td>11.1</td><td>11.1</td></tr><tr><td>4S</td><td>14.8</td><td>14.8</td></tr><tr><td>5S</td><td>18.5</td><td>18.5</td></tr><tr><td>6S</td><td>22.2</td><td>22.2</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameters</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_N_CELLS">BAT1_N_CELLS</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_N_CELLS">BAT2_N_CELLS</a>.</p></div><h3 id="충전-완료-전압-셀당" tabindex="-1">충전 완료 전압 (셀당) <a class="header-anchor" href="#충전-완료-전압-셀당" aria-label="Permalink to &quot;충전 완료 전압 (셀당)&quot;">​</a></h3><p>This sets the <em>nominal</em> maximum voltage of each cell (the lowest voltage at which the cell will be considered &quot;full&quot;).</p><p>이 값은 배터리의 공칭 최대 셀 전압보다 약간 낮게 설정하여야하지만, 몇 분간의 비행후에도 예상 용량이 100%가 될 정도로 낮지 않아야 합니다.</p><p>사용할 적절한 값은 다음과 같습니다.</p><ul><li><strong>LiPo:</strong> 4.05V (default in <em>QGroundControl</em>)</li><li><strong>LiIon:</strong> 4.05V</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The voltage of a full battery may drop a small amount over time after charging. 최대 값보다 약간 낮게 설정하여 이 하락값을 보정합니다.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameters</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_V_CHARGED">BAT1_V_CHARGED</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_CHARGED">BAT2_V_CHARGED</a>.</p></div><h3 id="방전-전압-셀-당" tabindex="-1">방전 전압 (셀 당) <a class="header-anchor" href="#방전-전압-셀-당" aria-label="Permalink to &quot;방전 전압 (셀 당)&quot;">​</a></h3><p>이는 각 셀의 공칭 최소 안전 전압을 설정합니다. 이 전압 미만을 사용하면 배터리가 손상될 수 있습니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There is no single value at which a battery is said to be empty. 너무 낮은 값을 선택하면 과방전으로 인해 배터리가 손상될 수 있습니다 (그리고, 기체 충돌이 발생할 수 있습니다). 너무 높은 값을 선택하면 비행 시간이 줄어듭니다.</p></div><p>최소 셀당 전압에 대한 경험 규칙</p><table tabindex="0"><thead><tr><th>단계</th><th>LiPo (V)</th><th>LiIon (V)</th></tr></thead><tbody><tr><td>보수적 (무부하 전압)</td><td>3.7</td><td>3</td></tr><tr><td>&quot;Real&quot; minimum (voltage under load/while flying)</td><td>3.5</td><td>2.7</td></tr><tr><td>배터리 손상 (부하 전압)</td><td>3.0</td><td>2.5</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Below the conservative range, the sooner you recharge the battery the better - it will last longer and lose capacity slower.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameter</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_V_EMPTY">BAT1_V_EMPTY</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_EMPTY">BAT2_V_EMPTY</a>.</p></div><h3 id="전압-분배기" tabindex="-1">전압 분배기 <a class="header-anchor" href="#전압-분배기" aria-label="Permalink to &quot;전압 분배기&quot;">​</a></h3><p>If you have a vehicle that measures voltage through a power module and the ADC of the flight controller then you should calibrate the measurements once per power module. To calibrate, the actual voltage from the battery is measured (using a multimeter) and compared to the value provided by the power module. This is used to calculate a &quot;voltage divider&quot; value, which can subsequently be used to scale the power module measurement to the correct value.</p><p>The easiest way to perform this calibration is by using <em>QGroundControl</em> and following the step-by-step guide on <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/power.html" target="_blank" rel="noreferrer">Setup &gt; Power Setup</a> (QGroundControl User Guide).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to parameters: <a href="./../advanced_config/parameter_reference.html#BAT1_V_DIV">BAT1_V_DIV</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_DIV">BAT2_V_DIV</a>.</p></div><h3 id="current_divider" tabindex="-1">Amps per volt <a class="header-anchor" href="#current_divider" aria-label="Permalink to &quot;Amps per volt {#current_divider}&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This calibration is not needed if your power module does not provide current measurements.</p></div><p>Current measurements are used (by default) for <a href="#load_compensation">Load Compensation</a> and <a href="#current_integration">Current Integration</a> if provided by the power module. The amps per volt divider must be calibrated to ensure an accurate current measurement.</p><p>The easiest way to calibrate the dividers is by using <em>QGroundControl</em> and following the step-by-step guide on <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/power.html" target="_blank" rel="noreferrer">Setup &gt; Power Setup</a> (QGroundControl User Guide).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to parameter(s): <a href="./../advanced_config/parameter_reference.html#BAT1_A_PER_V">BAT1_A_PER_V</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_A_PER_V">BAT2_A_PER_V</a>.</p></div><h2 id="load_compensation" tabindex="-1">Voltage-based Estimation with Load Compensation <a class="header-anchor" href="#load_compensation" aria-label="Permalink to &quot;Voltage-based Estimation with Load Compensation {#load_compensation}&quot;">​</a></h2><p>When a current flows through a battery, the internal resistance causes a voltage drop, reducing the measured output voltage of the battery compared to its open-circuit (no-load) voltage. When using the <a href="#basic_settings">basic configuration</a>, the measured output voltage is what is used to estimate the available capacity, which means that the battery level will appear to fluctuate when you fly up and down, or otherwise change the load on the battery.</p><p><em>Load compensation</em> uses a measured or estimated value for the internal resistance to correct for changes under load, resulting in far less variation in the estimated capacity when flying. This is enabled by default when using a power module that provides current measurements.</p><p>To use the load compensation first set the <a href="#basic_settings">basic configuration</a>. The <em>Empty Voltage</em> (<a href="./../advanced_config/parameter_reference.html#BAT1_V_EMPTY">BATn_V_EMPTY</a>, where <code>n</code> is the battery number) should be set higher (than without compensation) because the compensated voltage gets used for the estimation (typically set a bit below the expected rest cell voltage when empty after use).</p><p>You will then need to calibrate the <a href="#current_divider">Amps per volt divider</a> in the basic settings screen (in order to get reliable current measurements).</p><p>PX4 uses current-based load compensation based on a <em>real-time estimate</em> of the internal resistance of the battery by default (real time estimates are enabled if <a href="./../advanced_config/parameter_reference.html#BAT1_R_INTERNAL">BAT1_R_INTERNAL=-1</a>). Using a real time estimate allows the compensation to adapt to changes in the internal resistance of the battery due to temperature changes during flight, as well as over time as the battery degrades.</p><p>The internal resistance can also be measured and <a href="./../advanced_config/parameters.html">set manually</a> in <a href="./../advanced_config/parameter_reference.html#BAT1_R_INTERNAL">BAT1_R_INTERNAL</a>. A positive value in this parameter will be used for the internal resistance instead of the estimated value (<code>0</code> disables load compensation altogether).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There are LiPo chargers that can measure the internal resistance of your battery. A typical value for LiPo batteries is 5mΩ per cell but this can vary with discharge current rating, age and health of the cells.</p></div><h2 id="current_integration" tabindex="-1">Voltage-based Estimation Fused with Current Integration <a class="header-anchor" href="#current_integration" aria-label="Permalink to &quot;Voltage-based Estimation Fused with Current Integration {#current_integration}&quot;">​</a></h2><p>This method is the most accurate way to measure relative battery consumption. 부팅시마다 새로 충전한 배터리를 정확하게 설정하면, 추정 품질이 스마트 배터리의 품질과 비슷해질 것입니다 (이론적으로 정확한 잔여 비행 시간 추정이 가능합니다).</p><p>The method evaluates the remaining battery capacity by <em>fusing</em> the voltage-based estimate for the available capacity with a current-based estimate of the charge that has been consumed. 전류를 정확하게 측정할 수있는 장치가 필요합니다.</p><p>이 기능을 활성화하려면:</p><ol><li><p>First set up accurate voltage estimation using <a href="#load_compensation">load compensation</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Including calibrating the <a href="#current_divider">Amps per volt divider</a> setting.</p></div></li></ol><p>:::</p><ol start="2"><li><p>Set the parameter <a href="./../advanced_config/parameter_reference.html#BAT1_CAPACITY">BAT1_CAPACITY</a> to around 90% of the advertised battery capacity (usually printed on the battery label).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Do not set this value too high as this may result in a poor estimation or sudden drops in estimated capacity.</p></div></li></ol><p>:::</p><hr><p><strong>Additional information</strong></p><p>시간 경과에 따라 소비된 전하의 추정치는 측정된 전류를 수학적으로 통합하여 생성됩니다 (이 접근법은 매우 정확한 소비 에너지의 추정치를 제공합니다).</p><p>시스템 시작시 PX4는 먼저 전압 기반 추정치를 사용하여 초기 배터리 충전량을 결정합니다. 그런 다음이 추정치를 현재 통합의 값과 융합하여 더 나은 추정치를 제공합니다. 융합된 각 추정치에 배치된 상대값은 배터리 상태에 따라 달라집니다. 배터리가 비워 질수록 전압 기반 추정치가 더 많이 융합됩니다. 이는 과방전을 방지합니다 (예 : 잘못된 용량으로 구성되었거나, 초기치가 잘못 되었기 때문).</p><p>항상 정상적인 전체 배터리로 시작하는 경우이 방법은 스마트 배터리에서 사용하는 방법과 유사합니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Current integration cannot be used on its own (without voltage-based estimation) because it has no way to determine the <em>initial</em> capacity. 전압 추정을 사용하면 초기 용량을 추정하고 가능한 오류에 대한 지속적인 피드백을 제공할 수 있습니다 (예 : 배터리에 결함이 있거나 다른 방법을 사용하여 계산된 용량간에 불일치가 있는 경우).</p></div>',71)]))}const f=a(s,[["render",n]]);export{b as __pageData,f as default};
